def get_cond_energy(self, z, ys, seq_indices=[], reweight=True, dis_temp=1.):
    logits_list = self.classify(z, seq_indices=seq_indices)

    weight_list = [1. for _ in range(len(logits_list))]
    if len(seq_indices) > 0 and reweight:
        weight_list = [0.1 for _ in range(len(logits_list) - 1)]
        weight_list += [10.] if self.n_classes_list[seq_indices[-1]] == 1 else [1.]

    energy_outs = []
    for j, logits in enumerate(logits_list):
        energy_neg_cond = self._get_single_cond_energy(logits, ys[:, j], dis_temp)
        energy_outs.append(energy_neg_cond * weight_list[j])

    if self.expr != '':
        energy_output = utils.logical_comb(self.expr, energy_outs)
    else:
        energy_output = torch.stack(energy_outs).sum(dim=0)

    return energy_output

def forward(self, z, ys, seq_indices=[], reweight=True, dis_temp=1.):
    energy_output = self.get_cond_energy(z, ys, seq_indices=seq_indices,
                    reweight=reweight, dis_temp=dis_temp) \
                    - torch.linalg.norm(z, dim=1) ** 2 * 0.5
    return energy_output

def logical_comb(s: str, es: list):
    stack = [0, '+']
    val = 0.
    s += '$'
    for c in s:

        if c.isnumeric():
            val = es[int(c)]
        elif c in ['+', '-', '*', ')', '$']:

            symbol = stack.pop()
            if symbol == '+':
                stack[-1] += val
            elif symbol == '-':
                alpha = torch.clamp(0.1 / torch.abs(val.detach().clone()), min=0, max=1.)
                stack[-1] -= val * alpha
            else:
                tl, tr, cof = 1.0, 1.0, 20.0  # these values work well
                stack[-1] = torch.log(torch.exp(stack[-1] * tl) * cof + torch.exp(val * tr))

            if c == ')':
                val = stack.pop()
                stack.pop()
            elif c in ['+', '-', '*']:
                stack.append(c)
                val = 0.

        elif c == '(':
            stack.append(c)
            stack.extend([0, '+'])

    return stack[-1]
